mapper.sql:
SELECT /* isry.itgcm.casemng.caseunity.SrvcGrPvsnMapper.selectSrvcGrPvsnList(서비스집단제공목록조회) */ ROWNUM AS SEQ , T1.REG_DT AS REG_DT -- 등록일자 , T1.RESRCE_NO AS RESRCE_NO -- 자원번호 , T1.RESRCE_NM AS RESRCE_NM -- 자원명 , T1.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T1.SRVC_PVSN_TTL_NM AS SRVC_EXCN_BIZ_NM -- 서비스실행사업명 , T1.SRVC_PVSN_MTHD_SE_CD AS SRVC_PVSN_MTHD_SE_CD -- 서비스제공방법구분코드 , T1.SRVC_PVSN_BGNG_YMD AS SRVC_PVSN_BGNG_YMD -- 서비스제공시작일자 , T1.SRVC_PVSN_END_YMD AS SRVC_PVSN_END_YMD -- 서비스제공종료일자 , T1.SRVC_PVSN_BGNG_HR AS SRVC_PVSN_BGNG_HR -- 서비스제공시작시간 , T1.SRVC_PVSN_END_HR AS SRVC_PVSN_END_HR -- 서비스제공종료시간 , T1.RSFR_INST_NO AS RSFR_INST_NO -- 자원제공주체번호 , NVL((SELECT INST_NM FROM SAA000 WHERE INST_NO = T1.RSFR_INST_NO), (SELECT INST_NM FROM SDA600 WHERE INST_NO = T1.RSFR_INST_NO)) AS RSFR_INST_NM -- 자원제공주체명 , T1.PIC_NO AS PIC_NO -- 담당자번호 , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 WHERE ENFSN_NO = T1.PIC_NO) AS PIC_NM -- 담당자명 , T1.SRVC_PVSN_NO AS SRVC_PVSN_NO -- 서비스제공번호 , T1.SRVC_PVSN_WHDA_YN AS SRVC_PVSN_WHDA_YN -- 서비스제공전일여부 , CASE WHEN T1.TRPR_CNT > 1 THEN C##RG.DEC_B64(T1.TRPR_NM_ENCPT) || ' 외 ' || T1.CNT || '명' ELSE C##RG.DEC_B64(T1.TRPR_NM_ENCPT) END AS TRPR_CNT --대상자 , T1.FRST_REG_DT FROM ( SELECT TO_CHAR(T2.FRST_REG_DT, 'YYYYMMDD') AS REG_DT -- 등록일자 , T2.RESRCE_NO AS RESRCE_NO -- 자원번호 , T2.SRVC_PVSN_TTL_NM AS SRVC_PVSN_TTL_NM -- 서비스제공제목명 , T2.FRST_REG_DT AS FRST_REG_DT , T3.PVSN_RESRCE_NM AS RESRCE_NM -- 자원명 , T3.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T2.SRVC_PVSN_MTHD_SE_CD AS SRVC_PVSN_MTHD_SE_CD -- 서비스제공방법구분코드 , TO_CHAR(TO_DATE(T2.SRVC_PVSN_BGNG_YMD), 'YYYYMMDD') AS SRVC_PVSN_BGNG_YMD -- 서비스제공시작일자 , TO_CHAR(TO_DATE(T2.SRVC_PVSN_END_YMD) , 'YYYYMMDD') AS SRVC_PVSN_END_YMD -- 서비스제공종료일자 , T2.SRVC_PVSN_BGNG_HR AS SRVC_PVSN_BGNG_HR -- 서비스제공시작시간 , T2.SRVC_PVSN_END_HR AS SRVC_PVSN_END_HR -- 서비스제공종료시간 , T3.RSFR_INST_NO AS RSFR_INST_NO -- 자원제공주체번호 , T2.PIC_NO AS PIC_NO -- 담당자번호 , T2.TKCG_INST_NO AS TKCG_INST_NO -- 담당기관 , T2.SRVC_PVSN_NO AS SRVC_PVSN_NO -- 서비스제공번호 , T2.SRVC_PVSN_WHDA_YN AS SRVC_PVSN_WHDA_YN -- 서비스제공전일여부 , T2.SRVC_EXCN_BIZ_NO AS SEB500_SRVC_EXCN_BIZ_NO , T3.SRVC_EXCN_BIZ_NO AS SDA100_SRVC_EXCN_BIZ_NO , X.TRPR_CNT , X.TRPR_NM_ENCPT , X.CNT FROM SEB500 T2 JOIN SDA100 T3 ON T2.RESRCE_NO = T3.RESRCE_NO LEFT JOIN ( SELECT A.SRVC_PVSN_NO , COUNT(A.CASE_MNG_NO) AS TRPR_CNT , COUNT(A.CASE_MNG_NO) -1 AS CNT , MAX(C.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT FROM SEB510 A LEFT JOIN SEB100 B ON A.CASE_MNG_NO = B.CASE_MNG_NO AND A.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO LEFT JOIN SEA200 C ON B.TRPR_INFO_NO = C.TRPR_INFO_NO
WHERE 1=1 AND A.DEL_YN != 'Y'
GROUP BY A.SRVC_PVSN_NO ) X ON T2.SRVC_PVSN_NO = X.SRVC_PVSN_NO
WHERE 1=1
AND TO_CHAR(T2.FRST_REG_DT, 'YYYYMMDD') BETWEEN #{START_DATE} AND #{END_DATE}
AND T3.PVSN_RESRCE_NM LIKE '%'||#{PVSN_RESRCE_NM}||'%'
AND T3.SRVC_TYPE_SE_CD = #{SRVC_TYPE_SE_CD}
AND T2.SRVC_PVSN_MTHD_SE_CD = #{SRVC_PVSN_MTHD_SE_CD}
AND T2.SRVC_PVSN_TTL_NM LIKE '%'||#{SRVC_EXCN_BIZ_NM}||'%'
AND T2.DEL_YN != 'Y' AND T2.SRVC_GR_PVSN_YN = 'Y' /* 집단제공 */ AND T3.USE_YN = 'Y' ) T1 WHERE 1 = 1
/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
AND((SELECT INST_NM FROM SAA000 WHERE INST_NO = T1.RSFR_INST_NO) LIKE '%'||#{RSFR_INST_NM}||'%' OR T1.RSFR_INST_NO = #{RSFR_INST_NO})

mapper.select:
SELECT #{TOT_CNT} AS TOT_CNT , T.* FROM (
) T WHERE 1 = 1
AND T.SEQ >= #{START_IDX} AND T.SEQ <= #{LAST_IDX}
ORDER BY T.FRST_REG_DT DESC

SELECT /* isry.itgcm.casemng.caseunity.SrvcGrPvsnMapper.selectSrvcGrPvsnList(서비스집단제공목록조회) */ COUNT(*) OVER() AS TOT_CNT --공통추가 , T1.REG_DT AS REG_DT -- 등록일자 , T1.RESRCE_NO AS RESRCE_NO -- 자원번호 , T1.RESRCE_NM AS RESRCE_NM -- 자원명 , T1.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T1.SRVC_PVSN_TTL_NM AS SRVC_EXCN_BIZ_NM -- 서비스실행사업명 , T1.SRVC_PVSN_MTHD_SE_CD AS SRVC_PVSN_MTHD_SE_CD -- 서비스제공방법구분코드 , T1.SRVC_PVSN_BGNG_YMD AS SRVC_PVSN_BGNG_YMD -- 서비스제공시작일자 , T1.SRVC_PVSN_END_YMD AS SRVC_PVSN_END_YMD -- 서비스제공종료일자 , T1.SRVC_PVSN_BGNG_HR AS SRVC_PVSN_BGNG_HR -- 서비스제공시작시간 , T1.SRVC_PVSN_END_HR AS SRVC_PVSN_END_HR -- 서비스제공종료시간 , T1.RSFR_INST_NO AS RSFR_INST_NO -- 자원제공주체번호 , NVL((SELECT INST_NM FROM SAA000 WHERE INST_NO = T1.RSFR_INST_NO), (SELECT INST_NM FROM SDA600 WHERE INST_NO = T1.RSFR_INST_NO)) AS RSFR_INST_NM -- 자원제공주체명 , T1.PIC_NO AS PIC_NO -- 담당자번호 , (SELECT FLNM_ENCPT FROM SCA100 WHERE ENFSN_NO = T1.PIC_NO) AS PIC_NM -- 담당자명 , T1.SRVC_PVSN_NO AS SRVC_PVSN_NO -- 서비스제공번호 , T1.SRVC_PVSN_WHDA_YN AS SRVC_PVSN_WHDA_YN -- 서비스제공전일여부 , CASE WHEN T1.TRPR_CNT > 1 THEN C##RG.DEC_B64(T1.TRPR_NM_ENCPT) || ' 외 ' || T1.CNT || '명' ELSE C##RG.DEC_B64(T1.TRPR_NM_ENCPT) END AS TRPR_CNT --대상자 FROM ( SELECT TO_CHAR(T2.FRST_REG_DT, 'YYYYMMDD') AS REG_DT -- 등록일자 , T2.RESRCE_NO AS RESRCE_NO -- 자원번호 , T2.SRVC_PVSN_TTL_NM AS SRVC_PVSN_TTL_NM -- 서비스제공제목명 , T3.PVSN_RESRCE_NM AS RESRCE_NM -- 자원명 , T3.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T2.SRVC_PVSN_MTHD_SE_CD AS SRVC_PVSN_MTHD_SE_CD -- 서비스제공방법구분코드 , TO_CHAR(TO_DATE(T2.SRVC_PVSN_BGNG_YMD), 'YYYYMMDD') AS SRVC_PVSN_BGNG_YMD -- 서비스제공시작일자 , TO_CHAR(TO_DATE(T2.SRVC_PVSN_END_YMD) , 'YYYYMMDD') AS SRVC_PVSN_END_YMD -- 서비스제공종료일자 , T2.SRVC_PVSN_BGNG_HR AS SRVC_PVSN_BGNG_HR -- 서비스제공시작시간 , T2.SRVC_PVSN_END_HR AS SRVC_PVSN_END_HR -- 서비스제공종료시간 , T3.RSFR_INST_NO AS RSFR_INST_NO -- 자원제공주체번호 , T2.PIC_NO AS PIC_NO -- 담당자번호 , T2.TKCG_INST_NO AS TKCG_INST_NO -- 담당기관 , T2.SRVC_PVSN_NO AS SRVC_PVSN_NO -- 서비스제공번호 , T2.SRVC_PVSN_WHDA_YN AS SRVC_PVSN_WHDA_YN -- 서비스제공전일여부 , T2.SRVC_EXCN_BIZ_NO AS SEB500_SRVC_EXCN_BIZ_NO , T3.SRVC_EXCN_BIZ_NO AS SDA100_SRVC_EXCN_BIZ_NO , X.TRPR_CNT , X.TRPR_NM_ENCPT , X.CNT FROM SEB500 T2 JOIN SDA100 T3 ON T2.RESRCE_NO = T3.RESRCE_NO LEFT JOIN ( SELECT A.SRVC_PVSN_NO , COUNT(A.CASE_MNG_NO) AS TRPR_CNT , COUNT(A.CASE_MNG_NO) -1 AS CNT , MAX(C.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT FROM SEB510 A LEFT JOIN SEB100 B ON A.CASE_MNG_NO = B.CASE_MNG_NO AND A.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO LEFT JOIN SEA200 C ON B.TRPR_INFO_NO = C.TRPR_INFO_NO
WHERE 1=1 AND A.DEL_YN != 'Y'
GROUP BY A.SRVC_PVSN_NO ) X ON T2.SRVC_PVSN_NO = X.SRVC_PVSN_NO
WHERE 1=1
AND TO_CHAR(T2.FRST_REG_DT, 'YYYYMMDD') BETWEEN #{START_DATE} AND #{END_DATE}
AND T3.PVSN_RESRCE_NM LIKE '%'||#{PVSN_RESRCE_NM}||'%'
AND T3.SRVC_TYPE_SE_CD = #{SRVC_TYPE_SE_CD}
AND T2.SRVC_PVSN_MTHD_SE_CD = #{SRVC_PVSN_MTHD_SE_CD}
AND T2.SRVC_PVSN_TTL_NM LIKE '%'||#{SRVC_EXCN_BIZ_NM}||'%'
AND T2.DEL_YN != 'Y' AND T2.SRVC_GR_PVSN_YN = 'Y' /* 집단제공 */ AND T3.USE_YN = 'Y' ORDER BY T2.FRST_REG_DT ) T1 WHERE 1 = 1
/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
AND((SELECT INST_NM FROM SAA000 WHERE INST_NO = T1.RSFR_INST_NO) LIKE '%'||#{RSFR_INST_NM}||'%' OR T1.RSFR_INST_NO = #{RSFR_INST_NO})
ORDER BY T1.SRVC_PVSN_NO DESC

SELECT /* isry.itgcm.casemng.caseunity.SrvcGrPvsnMapper.selectCaseGrExcnDetail(서비스집단제공상세조회) */ DISTINCT T1.REG_DATE AS REG_DATE -- 등록일자 , T1.RESRCE_NO AS RESRCE_NO -- 자원번호 , T1.ORG_RESRCE_NO AS ORG_RESRCE_NO -- 자원번호 , T1.RESRCE_NM AS RESRCE_NM -- 자원명 , CASE WHEN T1.SRVC_EXCN_BIZ_CHC_PSBLTY_YN = 'Y' THEN T1.SEB500_SRVC_EXCN_BIZ_NO ELSE '' END AS SRVC_EXCN_BIZ_NO -- 서비스실행사업번호 , (SELECT X.SRVC_EXCN_BIZ_NM FROM SDA420 X WHERE X.SRVC_EXCN_BIZ_NO = CASE WHEN T1.SRVC_EXCN_BIZ_CHC_PSBLTY_YN = 'Y' THEN T1.SEB500_SRVC_EXCN_BIZ_NO ELSE T1.SDA100_SRVC_EXCN_BIZ_NO END) AS SRVC_EXCN_BIZ_NM -- 서비스실행사업명 , T1.SRVC_PVSN_MTHD_SE_CD AS SRVC_PVSN_MTHD_SE_CD -- 서비스제공방법구분코드 , T1.SRVC_PVSN_BGNG_YMD AS SRVC_PVSN_BGNG_YMD -- 서비스제공시작일자 , T1.SRVC_PVSN_END_YMD AS SRVC_PVSN_END_YMD -- 서비스제공종료일자 , T1.SRVC_PVSN_BGNG_HR AS SRVC_PVSN_BGNG_HR -- 서비스제공시작시간 , T1.SRVC_PVSN_END_HR AS SRVC_PVSN_END_HR -- 서비스제공종료시간 , T1.RSFR_INST_NO AS RSFR_INST_NO -- 자원제공주체번호 , NVL((SELECT INST_NM FROM SAA000 WHERE INST_NO = T1.RSFR_INST_NO), (SELECT INST_NM FROM SDA600 WHERE INST_NO = T1.RSFR_INST_NO)) AS RSFR_INST_NM -- 자원제공주체명 , T1.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T1.PIC_NO AS PIC_NO -- 담당자번호 , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 WHERE ENFSN_NO = T1.PIC_NO) AS PIC_NM -- 담당자명 , T1.TKCG_INST_NO AS TKCG_INST_NO -- 담당기관번호 , (SELECT INST_NM FROM SAA000 WHERE INST_NO = T1.TKCG_INST_NO) AS TKCG_INST_NM -- 담당기관명 , T1.SRVC_PVSN_CN AS SRVC_PVSN_CN -- 서비스목표내용 , T1.SRVC_PVSN_TTL_NM AS SRVC_PVSN_TTL_NM -- 서비스제공제목명 , T1.SRVC_PVSN_NO AS SRVC_PVSN_NO -- 서비스제공번호 , T1.SRVC_PVSN_WHDA_YN AS SRVC_PVSN_WHDA_YN -- 서비스제공전일여부 , T1.SRVC_EXCN_BIZ_CHC_PSBLTY_YN AS SRVC_EXCN_BIZ_CHC_PSBLTY_YN -- 서비스실행사업선택가능여부 , T1.SRVC_GR_PVSN_YN AS SRVC_GR_PVSN_YN -- 서비스집단제공여부 , T1.ATFINO AS ATFINO -- 첨부파일번호 , T1.SRVC_RESRCE_LCLAS_SE_CD AS SRVC_RESRCE_LCLAS_SE_CD -- 서비스자원대분류구분코드 , T1.APRV_STTS_SE_CD AS APRV_STTS_SE_CD -- 승인상태구분코드 FROM ( SELECT TO_CHAR(T2.FRST_REG_DT, 'YYYY-MM-DD') AS REG_DATE -- 등록일자 , T1.RESRCE_NO AS RESRCE_NO -- 자원번호 , T1.RESRCE_NO AS ORG_RESRCE_NO -- 자원번호 , T3.PVSN_RESRCE_NM AS RESRCE_NM -- 자원명 , T2.SRVC_PVSN_MTHD_SE_CD AS SRVC_PVSN_MTHD_SE_CD -- 서비스제공방법구분코드 , TO_CHAR(TO_DATE(T2.SRVC_PVSN_BGNG_YMD), 'YYYYMMDD') AS SRVC_PVSN_BGNG_YMD -- 서비스제공시작일자 , TO_CHAR(TO_DATE(T2.SRVC_PVSN_END_YMD) , 'YYYYMMDD') AS SRVC_PVSN_END_YMD -- 서비스제공종료일자 , T2.SRVC_PVSN_BGNG_HR AS SRVC_PVSN_BGNG_HR -- 서비스제공시작시간 , T2.SRVC_PVSN_END_HR AS SRVC_PVSN_END_HR -- 서비스제공종료시간 , T3.RSFR_INST_NO AS RSFR_INST_NO -- 자원제공주체번호 , T3.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T3.SRVC_RESRCE_LCLAS_SE_CD AS SRVC_RESRCE_LCLAS_SE_CD-- 서비스자원대분류구분코드 , T3.APRV_STTS_SE_CD AS APRV_STTS_SE_CD -- 승인상태구분코드 , T2.PIC_NO AS PIC_NO -- 담당자번호 , T2.TKCG_INST_NO AS TKCG_INST_NO -- 담당기관번호 , T2.SRVC_PVSN_CN AS SRVC_PVSN_CN -- 서비스목표내용 , T2.SRVC_PVSN_TTL_NM AS SRVC_PVSN_TTL_NM -- 서비스제공제목명 , T1.SRVC_PVSN_NO AS SRVC_PVSN_NO -- 서비스제공번호 , T2.SRVC_PVSN_WHDA_YN AS SRVC_PVSN_WHDA_YN -- 서비스제공전일여부 , NVL(( SELECT Z.ADDTNG_MNG_VALUE3 FROM SAC100 Z WHERE Z.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND Z.CMMNS_CD_VALUE = #{UNT_TASKWK_SE_CD} ), 'N') AS SRVC_EXCN_BIZ_CHC_PSBLTY_YN -- 서비스실행사업선택가능여부 , T2.SRVC_GR_PVSN_YN AS SRVC_GR_PVSN_YN -- 서비스집단제공여부 , T2.ATFINO AS ATFINO -- 첨부파일번호 , T2.SRVC_EXCN_BIZ_NO AS SEB500_SRVC_EXCN_BIZ_NO , T3.SRVC_EXCN_BIZ_NO AS SDA100_SRVC_EXCN_BIZ_NO FROM SEB510 T1 /* 서비스제공대상자 */ , SEB500 T2 /* 서비스제공 */ , SDA100 T3 /* 자원기본 */ WHERE T1.SRVC_PVSN_NO = T2.SRVC_PVSN_NO AND T1.RESRCE_NO = T2.RESRCE_NO AND T1.RESRCE_NO = T3.RESRCE_NO AND T1.SRVC_PVSN_NO = #{SRVC_PVSN_NO}
AND T1.RESRCE_NO = #{RESRCE_NO}
AND T1.DEL_YN != 'Y' AND T2.DEL_YN != 'Y' AND T2.SRVC_GR_PVSN_YN = 'Y' AND T3.USE_YN = 'Y' ) T1

SELECT /* isry.itgcm.casemng.caseunity.SrvcGrPvsnMapper.selectSrvcGrPvsnHstrList(서비스집단제공 이력 불러오기) */ DISTINCT T1.SRVC_PVSN_NO AS SRVC_PVSN_NO -- 서비스제공번호 , T1.RESRCE_NO AS RESRCE_NO -- 자원번호 , T1.RESRCE_NM AS RESRCE_NM -- 자원명 , T1.RSFR_INST_NO AS RSFR_INST_NO -- 자원제공주체번호 , NVL((SELECT INST_NM FROM SAA000 WHERE INST_NO = T1.RSFR_INST_NO), (SELECT INST_NM FROM SDA600 WHERE INST_NO = T1.RSFR_INST_NO)) AS RSFR_INST_NM -- 자원제공주체명 , CASE WHEN T1.SRVC_EXCN_BIZ_CHC_PSBLTY_YN = 'Y' THEN T1.SEB500_SRVC_EXCN_BIZ_NO ELSE '' END AS SRVC_EXCN_BIZ_NO -- 서비스실행사업번호 , (SELECT X.SRVC_EXCN_BIZ_NM FROM SDA420 X WHERE X.SRVC_EXCN_BIZ_NO = CASE WHEN T1.SRVC_EXCN_BIZ_CHC_PSBLTY_YN = 'Y' THEN T1.SEB500_SRVC_EXCN_BIZ_NO ELSE T1.SDA100_SRVC_EXCN_BIZ_NO END) AS SRVC_EXCN_BIZ_NM -- 서비스실행사업명 , T1.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T1.SRVC_PVSN_MTHD_SE_CD AS SRVC_PVSN_MTHD_SE_CD -- 서비스제공방법구분코드 , T1.SRVC_PVSN_CN AS SRVC_PVSN_CN -- 서비스제공내용 , T1.SRVC_PVSN_TTL_NM AS SRVC_PVSN_TTL_NM -- 서비스제공제목명 , T1.SRVC_PVSN_BGNG_YMD AS SRVC_PVSN_BGNG_YMD -- 서비스제공시작일자 , T1.SRVC_PVSN_END_YMD AS SRVC_PVSN_END_YMD -- 서비스제공종료일자 , T1.SRVC_PVSN_BGNG_HR AS SRVC_PVSN_BGNG_HR -- 서비스제공시작시간 , T1.SRVC_PVSN_END_HR AS SRVC_PVSN_END_HR -- 서비스제공종료시간 , T1.PIC_NO AS PIC_NO -- 담당자번호 , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 WHERE ENFSN_NO = T1.PIC_NO) AS PIC_NM -- 담당자명 , T1.TKCG_INST_NO AS TKCG_INST_NO -- 담당기관번호 , (SELECT INST_NM FROM SAA000 WHERE INST_NO = T1.TKCG_INST_NO) AS TKCG_INST_NM -- 담당기관명 , T1.SRVC_PVSN_WHDA_YN AS SRVC_PVSN_WHDA_YN -- 서비스제공전일여부 , T1.SRVC_GR_PVSN_YN AS SRVC_GR_PVSN_YN -- 서비스집단제공여부 , T1.ATFINO AS ATFINO -- 첨부파일번호 FROM ( SELECT T1.SRVC_PVSN_NO AS SRVC_PVSN_NO -- 서비스제공번호 , T1.RESRCE_NO AS RESRCE_NO -- 자원번호 , T2.PVSN_RESRCE_NM AS RESRCE_NM -- 자원명 , T2.RSFR_INST_NO AS RSFR_INST_NO , T2.SRVC_EXCN_BIZ_NO AS SDA100_SRVC_EXCN_BIZ_NO , T1.SRVC_EXCN_BIZ_NO AS SEB500_SRVC_EXCN_BIZ_NO , T2.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T1.SRVC_PVSN_MTHD_SE_CD AS SRVC_PVSN_MTHD_SE_CD -- 서비스제공방법구분코드 , T1.SRVC_PVSN_CN AS SRVC_PVSN_CN -- 서비스제공내용 , T1.SRVC_PVSN_TTL_NM AS SRVC_PVSN_TTL_NM -- 서비스제공제목명 , T1.SRVC_PVSN_BGNG_YMD AS SRVC_PVSN_BGNG_YMD -- 서비스제공시작일자 , T1.SRVC_PVSN_END_YMD AS SRVC_PVSN_END_YMD -- 서비스제공종료일자 , T1.SRVC_PVSN_BGNG_HR AS SRVC_PVSN_BGNG_HR -- 서비스제공시작시간 , T1.SRVC_PVSN_END_HR AS SRVC_PVSN_END_HR -- 서비스제공종료시간 , T1.PIC_NO AS PIC_NO -- 담당자번호 , T1.TKCG_INST_NO AS TKCG_INST_NO -- 담당기관번호 , T1.SRVC_PVSN_WHDA_YN AS SRVC_PVSN_WHDA_YN -- 서비스제공전일여부 , NVL(( SELECT Z.ADDTNG_MNG_VALUE3 FROM SAC100 Z WHERE Z.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND Z.CMMNS_CD_VALUE = #{UNT_TASKWK_SE_CD} ), 'N') AS SRVC_EXCN_BIZ_CHC_PSBLTY_YN -- 서비스실행사업선택가능여부 , T1.SRVC_GR_PVSN_YN AS SRVC_GR_PVSN_YN -- 서비스집단제공여부 , T1.ATFINO AS ATFINO -- 첨부파일번호 FROM SEB500 T1 /* 서비스제공 */ , SDA100 T2 /* 자원기본 */ WHERE T1.RESRCE_NO = T2.RESRCE_NO AND T1.DEL_YN != 'Y' AND T2.USE_YN = 'Y' AND (T1.SRVC_PVSN_BGNG_YMD BETWEEN #{SRVC_PVSN_BGNG_YMD} AND #{SRVC_PVSN_END_YMD} OR T1.SRVC_PVSN_END_YMD BETWEEN #{SRVC_PVSN_BGNG_YMD} AND #{SRVC_PVSN_END_YMD} OR #{SRVC_PVSN_BGNG_YMD} BETWEEN T1.SRVC_PVSN_BGNG_YMD AND T1.SRVC_PVSN_END_YMD OR #{SRVC_PVSN_END_YMD} BETWEEN T1.SRVC_PVSN_BGNG_YMD AND T1.SRVC_PVSN_END_YMD) AND #{UNT_TASKWK_SE_CD} IN ( SELECT Y.UNT_TASKWK_SE_CD FROM SEB510 X /* 서비스제공대상자 */ , SEB100 Y /* 사례기본 */ WHERE X.SRVC_PVSN_NO = T1.SRVC_PVSN_NO AND X.RESRCE_NO = T1.RESRCE_NO AND X.CASE_MNG_NO = Y.CASE_MNG_NO AND X.CASE_MNG_ODRNO = Y.CASE_MNG_ODRNO GROUP BY Y.UNT_TASKWK_SE_CD ) and T1.TKCG_INST_NO = #{TKCG_INST_NO}
AND T2.PVSN_RESRCE_NM LIKE '%'||#{RESRCE_NM}||'%'
ORDER BY T1.SRVC_PVSN_BGNG_YMD DESC ) T1
